const r = $input.item.json;
const cfg = r.cfg || {};
const url = (r.Links || '').trim();
const rid = r.id;
let platform = 'generic';
const u = url.toLowerCase();
if (u.includes('linkedin.com')) platform = 'linkedin';
else if (u.includes('tiktok.com')) platform = 'tiktok';
else if (u.includes('instagram.com')) platform = 'instagram';
else if (u.includes('youtube.com') || u.includes('youtu.be')) platform = 'youtube';
else if (u.match(/\.pdf($|\?)/)) platform = 'pdf';
return [{ json: { record_id: rid, source_url: url, platform, source_name: r['Source Name'] || '', cfg } }];

