const ctx = $('3. Detect Platform').item.json;
const b = $input.first().json;
const arr = Array.isArray(b) ? b : (b.data || b.messages || b.events || []);

const extractJson = (t) => {
  let c = String(t || '').replace(/```json/gi, '').replace(/```/g, '').trim();
  const s = c.indexOf('{');
  const e = c.lastIndexOf('}');
  if (s < 0 || e <= s) return null;
  const slice = c.slice(s, e + 1);
  try {
    const o = JSON.parse(slice);
    if (o && typeof o === 'object' && (('topic' in o) || ('text' in o))) return slice;
  } catch (err) { return null; }
  return null;
};

let inlineText = '';
let fileUrl = '';

if (Array.isArray(arr)) {
  for (const m of arr) {
    const am = m && m.assistant_message;
    if (!am) continue;
    const payload = extractJson(am.content);
    if (payload) inlineText = payload;
    for (const a of (am.attachments || [])) {
      if (a && a.url && (/\.json/i.test(a.url) || /json/i.test(a.content_type || ''))) fileUrl = a.url;
    }
  }
}

const taskId = $('4a. Manus Create Task').item.json.task_id || $('4a. Manus Create Task').item.json.id || '';

return [{ json: { ...ctx, manus_file_url: fileUrl, manus_inline_text: inlineText, manus_task_url: taskId ? ('https://manus.im/app/' + taskId) : '' } }];

const ctx = $('5. Manus Parse').item.json;
let d = {};
let rawSource = '';
if (ctx.manus_file_url) {
  let body = $input.first().json;
  if (body && typeof body.data === 'string') rawSource = body.data;
  else if (typeof body === 'string') rawSource = body;
  else if (body && typeof body === 'object') { rawSource = JSON.stringify(body); }
} else if (ctx.manus_inline_text) {
  rawSource = ctx.manus_inline_text;
}
let raw = String(rawSource).replace(/```json/gi,'').replace(/```/g,'').trim();
if (raw && raw[0] !== '{') { const s = raw.indexOf('{'); const e = raw.lastIndexOf('}'); if (s>=0 && e>s) raw = raw.slice(s,e+1); }
try { d = JSON.parse(raw); } catch(e) { d = { text: ctx.manus_inline_text || '' }; }
const media = [];
(d.image_urls || []).forEach(x => { if (x) media.push(x); });
(d.pdf_urls || []).forEach(x => { if (x) media.push(x); });
const text = d.text || '';
const topic = (d.topic || text.split('\n')[0] || 'Source Post').slice(0, 120);
const valid = ['News','Education','Product','Tech'];
const synonyms = { news:'News', breaking:'News', education:'Education', educational:'Education', learning:'Education', tutorial:'Education', guide:'Education', howto:'Education', product:'Product', launch:'Product', feature:'Product', release:'Product', tech:'Tech', technology:'Tech', technical:'Tech', ai:'Tech', software:'Tech', engineering:'Tech' };
let category = '';
const rawCat = (d.category || '').toString().trim();
if (rawCat) {
  const exact = valid.find(v => v.toLowerCase() === rawCat.toLowerCase());
  if (exact) { category = exact; }
  else {
    const key = rawCat.toLowerCase().replace(/[^a-z]/g,'');
    if (synonyms[key]) category = synonyms[key];
    else { const partial = valid.find(v => rawCat.toLowerCase().includes(v.toLowerCase()) || v.toLowerCase().includes(rawCat.toLowerCase())); if (partial) category = partial; }
  }
}
if (!category) category = 'Tech';
let publishDate = (d.publish_date || '').trim();
if (!/^\d{4}-\d{2}-\d{2}$/.test(publishDate)) publishDate = '';

const tz = (ctx.cfg && ctx.cfg.timezone) || 'Asia/Manila';
const genDate = $now.setZone(tz).toFormat('yyyy-MM-dd');
const shortId = ctx.record_id ? String(ctx.record_id).substring(0,7) : 'norec';
let slug = topic.toLowerCase().replace(/[^a-z0-9\s-]/g,'').replace(/\s+/g,'-').replace(/-+/g,'-').replace(/^-|-$/g,'');
if (slug.length > 40) { slug = slug.substring(0,40); const cut = slug.lastIndexOf('-'); if (cut > 15) slug = slug.substring(0,cut); }
slug = slug.replace(/^-|-$/g,'') || 'source-post';
const subfolderName = genDate + '_' + slug + '_' + shortId;

return [{ json: { record_id: ctx.record_id, source_url: ctx.source_url, platform: ctx.platform, source_name: ctx.source_name, cfg: ctx.cfg, topic, scraped_text: text, media_urls: media, category, instagram_caption: d.instagram_caption || '', linkedin_caption: d.linkedin_caption || '', static_notes: d.static_notes || '', publish_date: publishDate, subfolder_name: subfolderName, gen_date: genDate, short_id: shortId } }];

const folderId = $input.first().json.id;
const ctx = $('5c. Parse Output').item.json;
const subfolderUrl = 'https://drive.google.com/drive/folders/' + folderId;
const out = [];
const media = ctx.media_urls || [];
if (media.length === 0) {
  out.push({ json: { ...ctx, folder_id: folderId, subfolder_url: subfolderUrl, media_url: null, media_index: 0, total_media: 0 } });
} else {
  media.forEach((m, i) => out.push({ json: { ...ctx, folder_id: folderId, subfolder_url: subfolderUrl, media_url: m, media_index: i, total_media: media.length } }));
}
return out;

const src = $input.first().json;
const loopItem = $('9. Prep Media List').item.json;
let link = '';
if (loopItem.media_url) {
  link = src.webViewLink || (src.id ? 'https://drive.google.com/file/d/' + src.id + '/view' : '');
}
return [{ json: { ...loopItem, drive_link: link } }];

const all = $('13. Collect Link').all().map(i => i.json);
const ctx = $('9. Prep Media List').first().json;
const links = all.map(x => x.drive_link).filter(Boolean);
return [{ json: {
  record_id: ctx.record_id,
  cfg: ctx.cfg,
  topic: ctx.topic,
  source_url: ctx.source_url,
  scraped_text: ctx.scraped_text || '',
  subfolder_url: ctx.subfolder_url,
  media_urls: links.join('\n'),
  category: ctx.category || 'Tech',
  instagram_caption: ctx.instagram_caption || '',
  linkedin_caption: ctx.linkedin_caption || '',
  static_notes: ctx.static_notes || '',
  publish_date: ctx.publish_date || ''
} }];

const ctx = $('3. Detect Platform').item.json;
const prev = $input.item.json;
return [{ json: { ...ctx, poll_attempt: (prev.poll_attempt || 0) + 1 } }];

const ctx = $('4b2. Poll Counter').item.json;
const MAX_POLL_ATTEMPTS = 45;
return [{ json: { ...ctx, poll_timed_out: (ctx.poll_attempt || 0) >= MAX_POLL_ATTEMPTS } }];

const OUTPUT_TYPE = 'ingest';
const clients = $('0d. Load Clients').all().map(i => i.json);
const outputs = $input.all().map(i => i.json);
const out = [];
for (const c of clients) {
  const name = c['Client_Name'];
  if (!name) continue;
  if (c['Static_Enabled'] !== true) continue;
  const row = outputs.find(o => o['Key'] === name + '::' + OUTPUT_TYPE);
  if (!row) continue;
  if (row['Enabled'] !== true) continue;
  if (!c['Static_Base_ID'] || !c['Drive_Shared_Drive_ID'] || !row['Drive_Folder_ID'] || !row['Manus_Project_ID']) continue;
  out.push({ json: {
    client_name: name,
    static_base_id: c['Static_Base_ID'],
    drive_shared_drive_id: c['Drive_Shared_Drive_ID'],
    brand_name: c['Brand_Name'] || name,
    timezone: c['Timezone'] || 'Asia/Manila',
    drive_folder_id: row['Drive_Folder_ID'],
    manus_project_id: row['Manus_Project_ID']
  }});
}
return out;

const loop = $('0g. Client Loop');
let cfg = null;
try { cfg = loop.item.json; } catch (e) { cfg = null; }
if (!cfg || !cfg.static_base_id) { throw new Error('Could not resolve client config for this iteration. Refusing to ingest against the wrong client.'); }
const recs = $input.all().filter(i => i.json && i.json.id);
if (!recs.length) { return [{ json: { has_record: false, cfg } }]; }
return [{ json: { ...recs[0].json, has_record: true, cfg } }];

const d = $input.item.json;
const ctx = $('9. Prep Media List').first().json;
const cfg = d.cfg || {};
const B = 'alfredaiNoteBoundary';
const SOURCE_TABLE = 'tbloAZ3EVCtVtCJrj';
const baseId = cfg.static_base_id || '';
const recId = d.record_id || '';
const atUrl = (baseId && recId) ? ('https://airtable.com/' + baseId + '/' + SOURCE_TABLE + '/' + recId) : '';
const links = String(d.media_urls || '').split('\n').filter(Boolean);
const lines = [
(cfg.brand_name || cfg.client_name || '') + ' Content Engine - ingested source folder',
'',
'Brand: ' + (cfg.brand_name || cfg.client_name || ''),
'Content type: Ingested source post',
'Ingested: ' + (ctx.gen_date || '') + ' (' + ((cfg.timezone || 'Asia/Manila').split('/')[1] || 'PHT') + ')',
'Topic: ' + (d.topic || ''),
'Platform: ' + (ctx.platform || ''),
'Source name: ' + (ctx.source_name || ''),
'Source URL: ' + (d.source_url || ''),
'Original publish date: ' + (d.publish_date || 'unknown'),
'',
'Airtable source record ID: ' + recId,
'Airtable source record: ' + atUrl,
'Airtable base: ' + baseId,
'',
'Source media files saved here: ' + links.length,
'',
'This folder holds the raw source material scraped from the link above, not generated output.',
'Generated assets for this topic live in Static Creation > Generated, in their own dated folders.'
];
const note = lines.join('\n');
const meta = JSON.stringify({ name: '00_INFO.txt', parents: [ctx.folder_id], mimeType: 'text/plain' });
const multipart = '--' + B + '\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n' + meta + '\r\n--' + B + '\r\nContent-Type: text/plain; charset=UTF-8\r\n\r\n' + note + '\r\n--' + B + '--';
return [{ json: { ...d, note_multipart: multipart } }];

const ctx=$('14b. Build Folder Note').item.json;
const {note_multipart,...rest}=ctx;
return{json:rest};
